('pep-prep', 'sexual-health', 'PEP / PrEP ยาป้องกันเอชไอวี', 'ให้คำปรึกษาเป็นความลับ ต้องนัดหมายทาง LINE ก่อนเข้ารับบริการ', '{"time": 1792543429314, "blocks": [{"id": "b0", "type": "paragraph", "data": {"text": "บริการ PEP (ยาต้านไวรัสหลังสัมผัสเชื้อ) และ PrEP (ยาป้องกันก่อนสัมผัสเชื้อ) พร้อมคำปรึกษาเป็นความลับ กรุณาทัก LINE เพื่อนัดหมายก่อนเข้ารับบริการทุกครั้ง"}}], "version": "2.29.1"}', null, null, 'สอบถามค่ายาทาง LINE @p49clinic', '[]'::jsonb, '{}'::text[], array['คำปรึกษาจากแพทย์เป็นความลับ']::text[], array['PEP ควรเริ่มยาโดยเร็วที่สุดหลังสัมผัสเชื้อ']::text[], null, null, 'pep-prep-2569', array['สุขภาพทางเพศ','HIV']::text[], 15, false, true)
